            )
        )
    }

    if let toCardinality = rel.toCardinality, !toCardinality.isEmpty {
        let p = rel.points[rel.points.count - 1]
        let prev = rel.points[rel.points.count - 2]
        let offset = _cardinalityOffset(from: p, to: prev)
        parts.append(
