              let canvas = d.canvas else { return false }
        let shared = canvas.undoManager === d.undoManager && d.undoManager?.canUndo == true
        canvas.undo(nil)
        pump(0.2)
        let clean = canvas.drawing.layers.count == 1 && !d.isDocumentEdited
